CREATE TABLE public.design_interpretation_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES public.projects(id),document_id uuid NOT NULL REFERENCES public.design_documents(id),design_version_id uuid NOT NULL,page_number integer NOT NULL CHECK(page_number>0),requested_by uuid NOT NULL REFERENCES public.profiles(id),model text NOT NULL,status text NOT NULL DEFAULT 'running' CHECK(status IN ('running','completed','failed','denied')),error_message text,run_id text,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(design_version_id,project_id) REFERENCES public.design_versions(id,project_id));
GRANT SELECT ON public.design_interpretation_runs TO authenticated; GRANT ALL ON public.design_interpretation_runs TO service_role;
ALTER TABLE public.design_interpretation_runs ENABLE ROW LEVEL SECURITY;
CREATE POLICY interpretation_runs_read ON public.design_interpretation_runs FOR SELECT TO authenticated USING(public.project_access(project_id) AND EXISTS(SELECT 1 FROM public.design_documents d WHERE d.id=document_id AND d.deleted_at IS NULL));
CREATE UNIQUE INDEX interpretation_active_page ON public.design_interpretation_runs(design_version_id,page_number) WHERE status='running';
CREATE TRIGGER interpretation_run_references BEFORE INSERT OR UPDATE ON public.design_interpretation_runs FOR EACH ROW EXECUTE FUNCTION public.validate_processing_references();
CREATE TABLE public.design_interpretations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),run_id uuid NOT NULL REFERENCES public.design_interpretation_runs(id),project_id uuid NOT NULL REFERENCES public.projects(id),document_id uuid NOT NULL REFERENCES public.design_documents(id),design_version_id uuid NOT NULL,element_type text NOT NULL,element_name text NOT NULL,deck text NOT NULL DEFAULT '',location text NOT NULL DEFAULT '',measured_value numeric,unit text,source_document text NOT NULL,page_number integer NOT NULL CHECK(page_number>0),confidence numeric NOT NULL CHECK(confidence BETWEEN 0 AND 1),verification_status text NOT NULL DEFAULT 'UNVERIFIED' CHECK(verification_status IN ('UNVERIFIED','VERIFIED','REJECTED')),information_origin text NOT NULL CHECK(information_origin IN ('DIRECTLY_OBSERVED','AI_INFERRED')),source_quote text NOT NULL DEFAULT '',original_element jsonb NOT NULL,reviewed_by uuid REFERENCES public.profiles(id),reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(design_version_id,project_id) REFERENCES public.design_versions(id,project_id),CHECK(information_origin<>'AI_INFERRED' OR (measured_value IS NULL AND unit IS NULL)),CHECK(verification_status='UNVERIFIED' OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)));
GRANT SELECT ON public.design_interpretations TO authenticated; GRANT ALL ON public.design_interpretations TO service_role;
ALTER TABLE public.design_interpretations ENABLE ROW LEVEL SECURITY;
CREATE POLICY interpretation_read ON public.design_interpretations FOR SELECT TO authenticated USING(public.project_access(project_id) AND EXISTS(SELECT 1 FROM public.design_documents d WHERE d.id=document_id AND d.deleted_at IS NULL));
CREATE TRIGGER interpretation_references BEFORE INSERT OR UPDATE ON public.design_interpretations FOR EACH ROW EXECUTE FUNCTION public.validate_processing_references();
CREATE FUNCTION public.interpretation_version_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF EXISTS(SELECT 1 FROM public.compliance_assessments WHERE design_version_id=NEW.design_version_id) THEN RAISE EXCEPTION 'Assessed versions cannot be changed'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.design_interpretation_runs r WHERE r.id=NEW.run_id AND r.design_version_id=NEW.design_version_id AND r.project_id=NEW.project_id AND r.document_id=NEW.document_id AND r.page_number=NEW.page_number) THEN RAISE EXCEPTION 'Interpretation run and source must match';END IF;
IF TG_OP='UPDATE' AND NEW.original_element IS DISTINCT FROM OLD.original_element THEN RAISE EXCEPTION 'Original interpretation is immutable';END IF;RETURN NEW;END $$;
CREATE TRIGGER interpretation_version_guard BEFORE INSERT OR UPDATE ON public.design_interpretations FOR EACH ROW EXECUTE FUNCTION public.interpretation_version_guard();
CREATE TABLE public.design_interpretation_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),interpretation_id uuid NOT NULL REFERENCES public.design_interpretations(id),project_id uuid NOT NULL REFERENCES public.projects(id),reviewer_id uuid NOT NULL REFERENCES public.profiles(id),decision text NOT NULL CHECK(decision IN ('UNVERIFIED','VERIFIED','REJECTED')),rationale text NOT NULL,before_element jsonb NOT NULL,after_element jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.design_interpretation_reviews TO authenticated; GRANT ALL ON public.design_interpretation_reviews TO service_role;
ALTER TABLE public.design_interpretation_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY interpretation_reviews_read ON public.design_interpretation_reviews FOR SELECT TO authenticated USING(public.project_access(project_id) AND EXISTS(SELECT 1 FROM public.design_interpretations i JOIN public.design_documents d ON d.id=i.document_id WHERE i.id=interpretation_id AND d.deleted_at IS NULL));
CREATE FUNCTION public.review_design_interpretation(_id uuid,_element jsonb,_decision text,_rationale text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item public.design_interpretations; updated public.design_interpretations; BEGIN
SELECT * INTO item FROM public.design_interpretations WHERE id=_id FOR UPDATE;
IF auth.uid() IS NULL OR item.id IS NULL OR NOT public.project_access(item.project_id,ARRAY['administrator','project_manager','engineer']::public.organization_role[]) OR NOT EXISTS(SELECT 1 FROM public.design_documents WHERE id=item.document_id AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Engineering membership required' USING ERRCODE='42501';END IF;
IF _decision NOT IN ('UNVERIFIED','VERIFIED','REJECTED') OR coalesce(length(trim(_rationale)),0)=0 OR length(_rationale)>4000 OR coalesce(length(trim(_element->>'element_name')),0)=0 OR coalesce(length(trim(_element->>'element_type')),0)=0 THEN RAISE EXCEPTION 'Element, decision and rationale required';END IF;
IF _element->>'information_origin' NOT IN ('DIRECTLY_OBSERVED','AI_INFERRED') THEN RAISE EXCEPTION 'Origin required';END IF;
IF _element->>'information_origin'='AI_INFERRED' AND (_element->>'measured_value' IS NOT NULL OR _element->>'unit' IS NOT NULL) THEN RAISE EXCEPTION 'Inferred dimensions cannot be measured values';END IF;
IF _element->>'measured_value' IS NOT NULL AND coalesce(length(trim(_element->>'source_quote')),0)=0 THEN RAISE EXCEPTION 'Measured values require source evidence';END IF;
UPDATE public.design_interpretations SET element_type=_element->>'element_type',element_name=_element->>'element_name',deck=coalesce(_element->>'deck',''),location=coalesce(_element->>'location',''),measured_value=(_element->>'measured_value')::numeric,unit=_element->>'unit',information_origin=_element->>'information_origin',source_quote=coalesce(_element->>'source_quote',''),verification_status=_decision,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() WHERE id=_id RETURNING * INTO updated;
INSERT INTO public.design_interpretation_reviews(interpretation_id,project_id,reviewer_id,decision,rationale,before_element,after_element) VALUES(item.id,item.project_id,auth.uid(),_decision,_rationale,to_jsonb(item),to_jsonb(updated));
INSERT INTO public.activity_logs(organization_id,project_id,actor_id,action,entity_type,entity_id,metadata) SELECT organization_id,item.project_id,auth.uid(),'interpretation_reviewed','design_interpretations',item.id,jsonb_build_object('decision',_decision,'rationale',_rationale) FROM public.projects WHERE id=item.project_id;END $$;
REVOKE ALL ON FUNCTION public.review_design_interpretation(uuid,jsonb,text,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.review_design_interpretation(uuid,jsonb,text,text) TO authenticated;
CREATE TABLE public.ai_interpretation_access(id text PRIMARY KEY,error_message text NOT NULL,status_code integer NOT NULL,blocked_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ai_interpretation_access TO service_role;
ALTER TABLE public.ai_interpretation_access ENABLE ROW LEVEL SECURITY;
COMMENT ON TABLE public.ai_interpretation_access IS 'Durable terminal access/credit pauses checked before all interpretation calls; no automated retries.';